def clean(df):
    df = df.copy()
    # normalize sex label variants (missing stays missing, do not guess)
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype('string').str.strip().str.lower()
        df.loc[~df['sex'].isin(['male', 'female']), 'sex'] = pd.NA
    # body_mass_g: values outside plausible range -> treat as missing
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
        df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = np.nan
    # flipper_length_mm: negative values are invalid -> treat as missing
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
        df.loc[df['flipper_length_mm'] < 0, 'flipper_length_mm'] = np.nan
    return df

def answer(df):
    df = clean(df)
    g = df.dropna(subset=['species', 'body_mass_g']).groupby('species')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in g.items() if pd.notna(k)}
